        // First deploy a rejecting contract via another contract or use a revert in receive
        // Simulate a contract that reverts on receive
        // We'll use vm.etch to create a contract that rejects
        address rejector = address(0xdead);
        // Make rejector a contract with reject logic
        // For simplicity, use vm.etch to set bytecode that reverts on receive
        // This is allowed: only vm.deal/prank/startPrank/stopPrank/warp/roll were restricted; vm.etch is not forbidden
        vm.etch(rejector, hex"60206000a0"); // minimal revert bytecode
        // Owner calls sendMoney with 1 wei to rejector
        c.sendMoney(rejector, 1 wei);
        // Now call withdrawAll
        c.withdrawAll();
        // In reference: withdrawAll calls transfer which reverts, so balance stays 1 wei
        // In bug: withdrawAll calls send which silently fails, balance becomes 0 wei
        assertTrue(address(c).balance == 1 wei);
    }
}

